"""Art of the HOME screen (firmware/src/organ_home_art.h), generated: do not edit the header by hand.

  python3 tools/gen_home_art.py          (reads docs/drawbar-heads-ref.png and assets/fonts/InterTight[wght].ttf)

The nine drawbar heads are crops of the reference picture (docs/drawbar-heads-ref.png), one per drawbar, resized to the
HOME's size (18 x 29 px) and stored as RGB565; a smaller set (14 x 23 px, 0.9.47) for HOME 2's pedal and lower drawbars,
18 px apart.
The two side frames (0.9.53, the owner's pictures docs/home-frame-left.png and docs/home-frame-right.png) are resized to
the frames' size on HOME (8 x 213 px, below the header) and stored as RGB565. The PERC label is the text rotated 90 degrees counter-clockwise, on black.
"""
import math
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parent.parent
REF = ROOT / "docs" / "drawbar-heads-ref.png"
FONT = ROOT / "assets" / "fonts" / "InterTight[wght].ttf"
OUT = ROOT / "firmware" / "src" / "organ_home_art.h"

HEAD_W, HEAD_H = 18, 29
SMALL_W, SMALL_H = 14, 23                            # HOME 2 (the pedal's two and the lower's nine, 18 px apart)
FRAME_W, FRAME_H = 8, 213                            # HOME's side frames: HU(20) wide, from HU(64) to the bottom
FRAMES = [ROOT / "docs" / "home-frame-left.png", ROOT / "docs" / "home-frame-right.png"]
CENTERS = [55 + i * 93.5 for i in range(9)]           # the nine heads' centres in the reference (px)
CROP_X, CROP_Y0, CROP_Y1 = 35, 292, 412              # half width of a head, its top and bottom rows


def rgb565(r, g, b):
    return ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3)


def heads(w=HEAD_W, h=HEAD_H):
    ref = Image.open(REF).convert("RGB")
    out = []
    for c in CENTERS:
        crop = ref.crop((round(c - CROP_X), CROP_Y0, round(c + CROP_X), CROP_Y1))
        out.append(crop.resize((w, h), Image.LANCZOS))
    return out


def perc():
    font = ImageFont.truetype(str(FONT), 9)
    tmp = Image.new("RGB", (40, 14), (0, 0, 0))
    ImageDraw.Draw(tmp).text((1, 1), "PERC", font=font, fill=(255, 255, 255))
    bbox = tmp.getbbox()
    tmp = tmp.crop(bbox)
    return tmp.rotate(90, expand=True)                 # counter-clockwise, reads bottom to top


def c_array(img):
    w, h = img.size
    return ",".join(f"0x{rgb565(*img.getpixel((x, y))):04x}" for y in range(h) for x in range(w))


def main():
    hs = heads()
    pc = perc()
    lines = [
        "/* SPDX-License-Identifier: GPL-3.0-only */",
        "/* GENERATED by tools/gen_home_art.py from docs/drawbar-heads-ref.png and the InterTight font: do not edit. */",
        "#ifndef ORGAN_HOME_ART_H",
        "#define ORGAN_HOME_ART_H",
        "",
        f"#define HOME_HEAD_W {HEAD_W}",
        f"#define HOME_HEAD_H {HEAD_H}",
        "/* the nine upper drawbar heads, left to right (RGB565, row by row) */",
        f"static const uint16_t HOME_HEAD[9][{HEAD_W * HEAD_H}] = {{",
    ]
    for h in hs:
        lines.append("    {" + c_array(h) + "},")
    lines += [
        "};",
        f"#define HOME_HEAD_SW {SMALL_W}",
        f"#define HOME_HEAD_SH {SMALL_H}",
        "/* the same nine heads, smaller: HOME 2's lower drawbars (and the pedal's, by their footage) */",
        f"static const uint16_t HOME_HEAD_S[9][{SMALL_W * SMALL_H}] = {{",
    ]
    for h in heads(SMALL_W, SMALL_H):
        lines.append("    {" + c_array(h) + "},")
    lines += [
        "};",
        f"#define HOME_FRAME_W {FRAME_W}",
        f"#define HOME_FRAME_H {FRAME_H}",
        "/* HOME's side frames, left and right (the owner's pictures, resized) */",
        f"static const uint16_t HOME_FRAME[2][{FRAME_W * FRAME_H}] = {{",
    ]
    for f in FRAMES:
        lines.append("    {" + c_array(Image.open(f).convert("RGB").resize((FRAME_W, FRAME_H), Image.LANCZOS)) + "},")
    lines += [
        "};",
        f"#define HOME_PERC_W {pc.width}",
        f"#define HOME_PERC_H {pc.height}",
        "/* sin(a) x 1000 for a = 0 .. 90 degrees: the knobs' and the selector's pointers (no floating point in the firmware) */",
        "static const int16_t HOME_SIN1000[91] = {" + ",".join(str(round(1000 * math.sin(math.radians(a)))) for a in range(91)) + "};",
        "/* the PERC label, rotated (RGB565 on black) */",
        f"static const uint16_t HOME_PERC[{pc.width * pc.height}] = {{" + c_array(pc) + "};",
        "",
        "#endif",
        "",
    ]
    OUT.write_text("\n".join(lines))
    print("wrote", OUT, "perc", pc.size)


if __name__ == "__main__":
    main()
